import{_ as l,l as n,o as e,c as r,v as t,p as s,x as i,d as E,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"节点名不再等于栅长","description":"","frontmatter":{"title":"节点名不再等于栅长","date":"2026-09-10T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/node-vs-gate-length.md","filePath":"litho/node-vs-gate-length.md","lastUpdated":1789023840000}'),d={name:"litho/node-vs-gate-length.md"};function c(A,a,m,B,_,f){const o=n("Mermaid");return e(),r("div",null,[a[1]||(a[1]=t('<h1 id="节点名不再等于栅长" tabindex="-1">节点名不再等于栅长 <a class="header-anchor" href="#节点名不再等于栅长" aria-label="Permalink to &quot;节点名不再等于栅长&quot;">​</a></h1><div class="epigraph"><p>工艺节点标签曾是栅长名义值；后来数字与物理栅长、甚至与最小图形尺寸脱钩，变成代际与路线图的综合标签。</p><footer>—— 据 Mack, Fundamental Principles of Optical Lithography 对临界尺寸与节点语言的区分整理</footer></div><p><a href="/litho/interconnect-halfpitch">上一课</a>把互连半节距与金属层引进规格。缺口是：为何口头上的「3 nm 节点」栅长不是 3 nm？读路线图与各层目标尺寸时，若把节点名当物理栅长，会系统性误判要画多细。名字是序号，表格才是尺子。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/mosfet-gate-length">MOSFET 与栅长</a> 曾经就是节点核心：名字里的纳米数，大约就是要印的栅。鳍式器件之后，有效沟道长度与栅图形的关系更绕；名字仍按大约 0.7 倍一代代往下叫，但数字不再对应某一单层的物理尺寸。缺口是命名史与物理量的分离，不是再定义一次半节距。名字是序号，表格才是尺子，不能把代际标签代入某一层 CD。</p><h3 id="节点名不是光刻目标的输入" tabindex="-1">节点名不是光刻目标的输入 <a class="header-anchor" href="#节点名不是光刻目标的输入" aria-label="Permalink to &quot;节点名不是光刻目标的输入&quot;">​</a></h3><p>光刻工程师看的是各层目标临界尺寸、节距、套刻预算，写在设计规则里。把「7 nm」代入某一公式当 \\(\\mathrm{CD}\\)，会得到与产线无关的数。节点名可以当谈话标签；计算与验收必须换成具体层的 \\(W\\)、\\(p\\) 与套刻。</p><p><span class="marginnote">平面时代「28 nm 节点」的多晶硅临界尺寸仍在三十纳米量级。鳍式时代「5 nm 节点」的接触多晶节距与金属节距是另一组更大的数。具体数字随厂家设计规则而变，本课只钉「不要 1:1 换算」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>节点名 ≈ 代际标签：综合接触多晶节距、金属节距、SRAM 单元面积、性能与功耗档。物理规格是一张表，不是一个数。三者必须分开：营销节点、有效栅长、最小金属宽度。查表，不要猜。</p><p>历史上名字跟着栅长走，是因为那一代最小图形差不多就是栅。互连层数变多、多重图形化出现之后，最小节距可能在金属而不在栅；鳍式器件的「栅长」甚至不再是平面上那条多晶硅的宽度。名字若仍按 0.7 倍往下叫，就只能当序号。路线图表格（各层 \\(p\\)、\\(W\\)、套刻）才是图形化输入。</p><p>图形化动机在脱钩之后仍然清楚：要缩小的是表上那些节距与孔，不是名字里的整数。名字继续缩小，是为了标记「下一代」；光刻是否跟得上，看的是表，不是名字。</p><p><span class="marginnote">ITRS/IRDS 一类路线图表格按层给出 pitch 与 overlay，从不把节点名当作可代入公式的 CD。Mack 讨论临界尺寸时对象也是具体层，不是代际绰号。</span></p>',13)),(e(),s(h,null,{default:i(()=>[p(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20NAME%5B%22%E8%8A%82%E7%82%B9%E5%90%8D%E6%A0%87%E7%AD%BE%22%5D%20--%3E%20LABEL%5B%22%E4%BB%A3%E9%99%85%E4%B8%8E%E8%90%A5%E9%94%80%22%5D%0A%20%20CPP%5B%22%E6%8E%A5%E8%A7%A6%E5%A4%9A%E6%99%B6%E8%8A%82%E8%B7%9D%22%5D%20--%3E%20SPEC%5B%22%E7%89%A9%E7%90%86%E8%A7%84%E6%A0%BC%E8%A1%A8%22%5D%0A%20%20MP%5B%22%E9%87%91%E5%B1%9E%E8%8A%82%E8%B7%9D%22%5D%20--%3E%20SPEC%0A%20%20GL%5B%22%E6%9C%89%E6%95%88%E6%A0%85%E9%95%BF%22%5D%20--%3E%20SPEC%0A%20%20SPEC%20--%3E%20LITHO%5B%22%E5%90%84%E5%B1%82%E7%9B%AE%E6%A0%87%E5%B0%BA%E5%AF%B8%22%5D%0A%20%20LABEL%20-.-%3E%7C%22%E4%B8%8D%E5%86%8D%E4%B8%80%E4%B8%80%E5%AF%B9%E5%BA%94%22%7C%20GL%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>脱钩之后，对外只报下一代节点，对内按层分配图形化难度。有的层先碰到单次曝光极限，有的层仍宽松。这解释了为何不能从节点名反推「这一代所有层都一样细」。下一课 <a href="/litho/contact-via-line">接触孔、通孔与线</a> 会说明孔层与线层甚至不在同一张难度表上。</p><p>同一代标签下，不同产品线的金属节距与单元面积也可以不同。逻辑、SRAM、模拟 IP 并不共享一张「节点 = 某纳米」的表。Foundry 对外一个名字，对内多套设计规则：这正是脱钩的日常形态。读新闻时把两家「同名节点」的栅长拿来比，会比错对象。</p><p>本课不把成像公式请回来填这个名。光学前置已经结束；成像主线在本课程末才从光程重开。这里只防止用错尺子：要印多细，问该层节距；名字只负责说「这是第几代谈话」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引用某一家代工厂的具体设计规则数值。不写某代技术何时导入新波长。鳍片、环栅的器件截面属于器件附录，本课只要「名字 ≠ \\(L\\)」。</p><p>SRAM 单元面积常被拿来「证明」节点进步，它是接触、栅、金属多层图形的乘积，更不能还原成单一栅长。名字继续叫小，表格里三项可以一项先动、两项后动。后课默认：节点名是标签；光刻目标来自各层节距与临界尺寸。下一课补竖直方向的孔与线的差别。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>节点名不再等于物理栅长，也不等于最小线宽。</li><li>光刻看各层 CD、节距与套刻，查规则手册而不是看名字。</li><li>脱钩后「下一代」仍要缩小表上的节距，只是尺子换成了表。</li><li>不要把节点数字代入成像公式当临界尺寸。</li><li>SRAM 面积与金属节距是表上的独立项，不能还原成单一 \\(L\\)；同名节点也不可直接比栅长。</li><li>出处：Mack, <em>Fundamental Principles of Optical Lithography</em>；Sze &amp; Ng, <em>Physics of Semiconductor Devices</em>。</li></ul>',9))])}const D=l(d,[["render",c]]);export{P as __pageData,D as default};
